  const cookieLocale = document.cookie.split("; ").find((item) => item.startsWith("ragscanner_locale="))?.split("=")[1];
  const browserLocale = navigator.language === "zh-CN" || navigator.language === "zh-SG" ? "zh-CN" : navigator.language.split("-")[0];
  const locale = languages[cookieLocale] ? cookieLocale : (languages[browserLocale] ? browserLocale : "en");
  const catalog = catalogs[locale] || {};
  const translate = (value) => {
    if (catalog[value]) return catalog[value];
    const viewAll = value.match(/^View all (\d+)$/);
    if (viewAll) return `${catalog["View all"] || "View all"} ${viewAll[1]}`;
    const enabledProfiles = value.match(/^(\d+) enabled profile\(s\)$/);
    if (enabledProfiles) return `${enabledProfiles[1]} ${catalog["enabled profile(s)"] || "enabled profile(s)"}`;
    const total = value.match(/^(\d+) total$/);
    if (total) return `${total[1]} ${catalog.total || "total"}`;
    const schedules = value.match(/^(\d+) schedule\(s\)$/);
    if (schedules) return `${schedules[1]} ${catalog["schedule(s)"] || "schedule(s)"}`;
    const minutes = value.match(/^Every (\d+) minute\(s\)$/);
    if (minutes) return `${catalog.Every || "Every"} ${minutes[1]} ${catalog["minute(s)"] || "minute(s)"}`;
    const findings = value.match(/^(\d+) finding\(s\) across the latest completed assessment$/);
    if (findings) return `${findings[1]} ${catalog["finding(s) across the latest completed assessment"] || "finding(s) across the latest completed assessment"}`;
    const ingestionIssues = value.match(/^(\d+) ingestion issue\(s\) reduced report coverage\. Review them below\.$/);
    if (ingestionIssues) return `${ingestionIssues[1]} ${catalog["ingestion issue(s) reduced report coverage. Review them below."] || "ingestion issue(s) reduced report coverage. Review them below."}`;
    const ingestionList = value.match(/^(\d+) ingestion issue\(s\) · open list$/);
    if (ingestionList) return `${ingestionList[1]} ${catalog["ingestion issue(s)"] || "ingestion issue(s)"} · ${catalog["open list"] || "open list"}`;
    const sourceStatus = value.match(/^(.+) · (API key needed|Ready|Detected only)$/);
    if (sourceStatus) return `${sourceStatus[1]} · ${catalog[sourceStatus[2]] || sourceStatus[2]}`;
    return value;
  };
  window.ragscannerTranslate = translate;
  document.documentElement.lang = languages[locale].locale;
  const requestedZone = document.body.dataset.timezone;
  const dateOptions = { dateStyle: "medium", timeStyle: "short" };
  if (requestedZone === "UTC") dateOptions.timeZone = "UTC";
  window.ragscannerFormatTime = (value) => {
    const parsed = new Date(value);
    return Number.isNaN(parsed.valueOf()) ? value : new Intl.DateTimeFormat(languages[locale].locale, dateOptions).format(parsed);
  };

  const translateTree = (root) => {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach((node) => {
      if (["SCRIPT", "STYLE", "CODE"].includes(node.parentElement?.tagName)) return;
      const value = node.nodeValue || "";
      const trimmed = value.trim();
      const translated = translate(trimmed);
      if (trimmed && translated !== trimmed) node.nodeValue = value.replace(trimmed, translated);
    });
    root.querySelectorAll("[placeholder],[aria-label],[title]").forEach((element) => {
      ["placeholder", "aria-label", "title"].forEach((attribute) => {
        const value = element.getAttribute(attribute);
        if (value) element.setAttribute(attribute, translate(value));
      });
    });
  };

  document.addEventListener("DOMContentLoaded", () => {
    document.querySelectorAll("[data-language-picker]").forEach((picker) => {
      picker.value = locale;
      picker.addEventListener("change", () => {
        document.cookie = `ragscanner_locale=${encodeURIComponent(picker.value)}; Path=/; SameSite=Strict; Max-Age=31536000`;
        window.location.reload();
      });
    });
    translateTree(document.body);
    document.querySelectorAll("time[data-local-time]").forEach((element) => {
      const parsed = new Date(element.dateTime || element.textContent);
      if (!Number.isNaN(parsed.valueOf())) {
        element.textContent = window.ragscannerFormatTime(parsed);
        element.title = parsed.toISOString();
      }
    });
  });
